import{_ as a,a as s,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第130–136课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第130–136课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第123–129课","link":"/life/english/new-concept/book-1/review-part-18"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第137–143课","link":"/life/english/new-concept/book-1/review-part-20"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第123–129课","link":"/life/english/new-concept/book-1/review-part-18"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第137–143课","link":"/life/english/new-concept/book-1/review-part-20"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-19.md","filePath":"life/english/new-concept/book-1/review-part-19.md"}'),n={name:"life/english/new-concept/book-1/review-part-19.md"};function r(i,e,l,h,d,p){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第130–136课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第130–136课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第130–136课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第130–136课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-130-·-情态动词-have-done" tabindex="-1">Lesson 130 · 情态动词 + have done <a class="header-anchor" href="#lesson-130-·-情态动词-have-done" aria-label="Permalink to &quot;Lesson 130 · 情态动词 + have done {#lesson-130-·-情态动词-have-done}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> He cannot have read the sign; it was covered.</p><h3 id="练习-1-129" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-129" aria-label="Permalink to &quot;练习 1 {#练习-1-129}&quot;">​</a></h3><p>选择 have/had：He cannot ___ read the sign.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 按本课规则判断：must have + 过去分词表示对过去的强推断，can&#39;t have + 过去分词表示认为过去不可能发生。它们不是现在完成时的普通肯否定，而是情态推断结构。过去状态用 have been，过去动作使用相应分词。速度等信息应作为证据，不要把猜测说成亲眼观察；本页只练语言，不判断实际交通责任。</p></details><p><strong>表达迁移：</strong> 围绕“根据现在的证据推测过去”写两至三句，再读给同伴听。至少使用一次情态动词 + have done，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>He cannot have read the sign; it was covered. The road is wet; it must have rained overnight.</p><p>Cannot have read 对过去是否读到标志作否定推断；it was covered 给出证据，但推断本身不是亲眼观察。 The road is wet 是现在证据；must have rained 对过去下雨作推断，overnight 指夜里。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-130">回看本课</a></p><h2 id="lesson-131-·-may-might-的时间层次" tabindex="-1">Lesson 131 · may/might 的时间层次 <a class="header-anchor" href="#lesson-131-·-may-might-的时间层次" aria-label="Permalink to &quot;Lesson 131 · may/might 的时间层次 {#lesson-131-·-may-might-的时间层次}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The parcel may arrive tomorrow.</p><h3 id="练习-1-130" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-130" aria-label="Permalink to &quot;练习 1 {#练习-1-130}&quot;">​</a></h3><p>填动词原形：The parcel may ___ (arrive).</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> arrive</p><p><strong>解析：</strong> 按本课规则判断：may/might + 原形表示现在或将来的可能，may/might have + 过去分词表示过去的可能。may be 是两词，maybe 是副词“也许”，不能在句法上直接互换。may not 意为可能不，通常不等于不可能；can&#39;t 才常用于有根据的排除。为保留不确定性，说明已知事实和猜测的界限。</p></details><p><strong>表达迁移：</strong> 围绕“讨论未确定的现在与过去可能”写两至三句，再读给同伴听。至少使用一次may/might 的时间层次，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The parcel may arrive tomorrow. Ella might have left her phone on the train.</p><p>May arrive 表未来可能，arrive 保持原形；tomorrow 表时间，整句不保证包裹一定到达。 Might have left 对过去遗落手机作不确定推断；on the train 说明可能遗落的地点。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-131">回看本课</a></p><h2 id="lesson-132-·-may-might-的时间层次" tabindex="-1">Lesson 132 · may/might 的时间层次 <a class="header-anchor" href="#lesson-132-·-may-might-的时间层次" aria-label="Permalink to &quot;Lesson 132 · may/might 的时间层次 {#lesson-132-·-may-might-的时间层次}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Ella might have left her phone on the train.</p><h3 id="练习-1-131" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-131" aria-label="Permalink to &quot;练习 1 {#练习-1-131}&quot;">​</a></h3><p>填分词：She might have ___ (leave) it on the train.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> left</p><p><strong>解析：</strong> 按本课规则判断：may/might + 原形表示现在或将来的可能，may/might have + 过去分词表示过去的可能。may be 是两词，maybe 是副词“也许”，不能在句法上直接互换。may not 意为可能不，通常不等于不可能；can&#39;t 才常用于有根据的排除。为保留不确定性，说明已知事实和猜测的界限。</p></details><p><strong>表达迁移：</strong> 围绕“讨论未确定的现在与过去可能”写两至三句，再读给同伴听。至少使用一次may/might 的时间层次，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Ella might have left her phone on the train. The parcel may arrive tomorrow.</p><p>Might have left 对过去遗落手机作不确定推断；on the train 说明可能遗落的地点。 May arrive 表未来可能，arrive 保持原形；tomorrow 表时间，整句不保证包裹一定到达。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-132">回看本课</a></p><h2 id="lesson-133-·-间接引语的时态回移" tabindex="-1">Lesson 133 · 间接引语的时态回移 <a class="header-anchor" href="#lesson-133-·-间接引语的时态回移" aria-label="Permalink to &quot;Lesson 133 · 间接引语的时态回移 {#lesson-133-·-间接引语的时态回移}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The reporter said that the bridge was closed.</p><h3 id="练习-1-132" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-132" aria-label="Permalink to &quot;练习 1 {#练习-1-132}&quot;">​</a></h3><p>按回移练习转述：He said, &quot;I am busy.&quot;</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He said that he was busy.</p><p><strong>解析：</strong> 按本课规则判断：过去时 said/told 引出转述时，原话的一般现在时常回移为一般过去时，现在进行时常回移为过去进行时。代词要随说话者身份调整。如果事实仍然成立或属于普遍事实，英语也允许保留原时态；不是所有转述都必须回移。say 与 tell 的结构不同，told 后通常要有听话者。</p></details><p><strong>表达迁移：</strong> 围绕“转述过去听到的消息”写两至三句，再读给同伴听。至少使用一次间接引语的时态回移，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The reporter said that the bridge was closed. Maya told us that she was studying abroad.</p><p>Said 为过去引述，that 从句采用 was；the bridge 是从句主语，closed 为状态表语。 Told 后保留听话者 us；she was studying 是转述内容，其中过去进行时可对应原话的 am studying。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-133">回看本课</a></p><h2 id="lesson-134-·-间接引语的时态回移" tabindex="-1">Lesson 134 · 间接引语的时态回移 <a class="header-anchor" href="#lesson-134-·-间接引语的时态回移" aria-label="Permalink to &quot;Lesson 134 · 间接引语的时态回移 {#lesson-134-·-间接引语的时态回移}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Maya told us that she was studying abroad.</p><h3 id="练习-1-133" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-133" aria-label="Permalink to &quot;练习 1 {#练习-1-133}&quot;">​</a></h3><p>选择 said/told：Maya ___ us that she was studying.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> told</p><p><strong>解析：</strong> 按本课规则判断：过去时 said/told 引出转述时，原话的一般现在时常回移为一般过去时，现在进行时常回移为过去进行时。代词要随说话者身份调整。如果事实仍然成立或属于普遍事实，英语也允许保留原时态；不是所有转述都必须回移。say 与 tell 的结构不同，told 后通常要有听话者。</p></details><p><strong>表达迁移：</strong> 围绕“转述过去听到的消息”写两至三句，再读给同伴听。至少使用一次间接引语的时态回移，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Maya told us that she was studying abroad. The reporter said that the bridge was closed.</p><p>Told 后保留听话者 us；she was studying 是转述内容，其中过去进行时可对应原话的 am studying。 Said 为过去引述，that 从句采用 was；the bridge 是从句主语，closed 为状态表语。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-134">回看本课</a></p><h2 id="lesson-135-·-would-与-had-done-的回移" tabindex="-1">Lesson 135 · would 与 had done 的回移 <a class="header-anchor" href="#lesson-135-·-would-与-had-done-的回移" aria-label="Permalink to &quot;Lesson 135 · would 与 had done 的回移 {#lesson-135-·-would-与-had-done-的回移}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> He said he would send the document the next day.</p><h3 id="练习-1-134" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-134" aria-label="Permalink to &quot;练习 1 {#练习-1-134}&quot;">​</a></h3><p>按回移转述：He said, &quot;I will send it.&quot;</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He said he would send it.</p><p><strong>解析：</strong> 按本课规则判断：在常见的过去转述中，will 变 would，have/has done 变 had done。tomorrow 可根据转述时间改为 the next day，yesterday 改为 the day before。转述时间仍是同一天时不必机械替换。先明确谁在何时说话，再转换人称与时间，不能只做单词替换而让事件时间改变。</p></details><p><strong>表达迁移：</strong> 围绕“转述将来的安排和已经完成的动作”写两至三句，再读给同伴听。至少使用一次would 与 had done 的回移，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>He said he would send the document the next day. She told me she had finished the repairs.</p><p>Would send 是过去视角中的将来；the next day 表相对于原说话日的第二天，不能随转述日期任意漂移。 Told me 为主句，had finished 表相对于过去告诉我的时点已完成；the repairs 为从句宾语。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-135">回看本课</a></p><h2 id="lesson-136-·-would-与-had-done-的回移" tabindex="-1">Lesson 136 · would 与 had done 的回移 <a class="header-anchor" href="#lesson-136-·-would-与-had-done-的回移" aria-label="Permalink to &quot;Lesson 136 · would 与 had done 的回移 {#lesson-136-·-would-与-had-done-的回移}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She told me she had finished the repairs.</p><h3 id="练习-1-135" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-135" aria-label="Permalink to &quot;练习 1 {#练习-1-135}&quot;">​</a></h3><p>按回移转述：She said, &quot;I have finished.&quot;</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She said she had finished.</p><p><strong>解析：</strong> 按本课规则判断：在常见的过去转述中，will 变 would，have/has done 变 had done。tomorrow 可根据转述时间改为 the next day，yesterday 改为 the day before。转述时间仍是同一天时不必机械替换。先明确谁在何时说话，再转换人称与时间，不能只做单词替换而让事件时间改变。</p></details><p><strong>表达迁移：</strong> 围绕“转述将来的安排和已经完成的动作”写两至三句，再读给同伴听。至少使用一次would 与 had done 的回移，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She told me she had finished the repairs. He said he would send the document the next day.</p><p>Told me 为主句，had finished 表相对于过去告诉我的时点已完成；the repairs 为从句宾语。 Would send 是过去视角中的将来；the next day 表相对于原说话日的第二天，不能随转述日期任意漂移。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-136">回看本课</a></p>',60)])])}const g=a(n,[["render",r]]);export{c as __pageData,g as default};
